/**
 * Body for `PATCH /api/drives/{id}/members/{kind}/{sid}`.
 */
export type UpdateDriveMemberDto = {
    /**
     * Optional. Pass `null` (or omit) to clear an existing expiry.
     */
    expires_at?: string | null;
    role: RoleDto;
};

/**
 * Body for `PATCH /api/drives/{id}/policies` (D5).
 *
 * Partial merge: any field left out of the JSON keeps its current
 * JSONB value (the repo uses `policies || $partial`). Each field
 * defaults to `false` in `DrivePolicies`, but the merge is keyed on
 * presence — so omitting a field means "leave it alone", not "set
 * it to false". Clients flip a single key at a time without
 * round-tripping the whole bag.
 */
export type UpdateDrivePoliciesDto = {
    forbid_cross_drive_move?: boolean | null;
    forbid_external_sharing?: boolean | null;
    forbid_owner_role_change?: boolean | null;
    forbid_public_links?: boolean | null;
    forbid_sharing?: boolean | null;
    include_in_music_index?: boolean | null;
    include_in_photo_index?: boolean | null;
    /**
     * Day cap on public links. Double `Option` so three states are
     * distinguishable on the wire, which a single `Option` collapses:
     *
     * * absent     → `None`       → leave whatever this drive has
     * * `null`     → `Some(None)` → REMOVE the override, inherit again
     * * a number   → `Some(Some)` → set the cap here
     *
     * Without the middle case there would be no way to stop overriding a
     * knob once you started — the drive would be pinned to its current
     * value forever, silently ignoring every future default change.
     *
     * `deserialize_with` is REQUIRED, not decoration. Plain
     * `#[serde(default)] Option<Option<u32>>` collapses the first two
     * states: serde maps a JSON `null` onto the OUTER `Option`, so both
     * absent and null arrive as `None` and the clear silently becomes a
     * no-op. Forcing the field through a deserializer that wraps whatever
     * it receives in `Some` is what keeps `null` distinguishable — the
     * deserializer only runs when the key is present.
     */
    max_public_link_days?: number | null;
    read_only?: boolean | null;
    require_public_link_password?: boolean | null;
};

/**
 * Body for `PATCH /api/drives/{id}/quota` (D4).
 *
 * `quota_bytes = null` (or ≤ 0) means unlimited — matches the DB
 * convention where NULL on the row is treated as "no cap" by
 * `storage_usage_service::check_drive_quota`. The service
 * normalises 0/negative to None before writing.
 */
export type UpdateDriveQuotaDto = {
    /**
     * New quota in bytes. `null` (or omitted) or ≤ 0 → unlimited.
     * A value below the drive's current `used_bytes` is accepted
     * intentionally (soft-quota semantic — new writes gated,
     * existing content untouched; owners recover by deleting
     * until the drive comes back under the cap).
     */
    quota_bytes?: number | null;
};

export type UpdateGroupRequest = {
    /**
     * Reserved for future use; v1 only persists the name in `rename`.
     */
    description?: string | null;
    name?: string | null;
};

export type UpdatePlaylistDto = {
    cover_file_id?: string | null;
    description?: string | null;
    is_public?: boolean | null;
    name?: string | null;
};

/**
 * Partial-update body for `PATCH /api/auth/me/profile` (PR 24).
 *
 * Each field is **optional**:
 * - **absent** → no change to that field.
 * - **present** → set / claim.
 *
 * **Username is claim-once, immutable.** This endpoint accepts
 * `username` only when the caller currently has none — passing it
 * when one is already claimed is rejected with `409 UsernameImmutable`.
 * The immutability avoids the NextCloud / DAV client breakage that
 * would otherwise come from renaming (paths under
 * `/remote.php/dav/files/{user}/…` and the `verify_url_user` check
 * both bake the username in as a stable identifier). If a user really
 * typoed their handle and needs to fix it, an admin override is the
 * escape hatch.
 *
 * **Given / family name** are freely settable. Any non-empty value
 * replaces the current one. Clearing back to `None` is out of scope
 * for v1.
 *
 * **OIDC-linked users are rejected wholesale with 403** — their
 * profile fields are managed at the IdP. The IdP is the source of
 * truth; mirroring writes here would just create a divergence.
 */
export type UpdateProfileDto = {
    /**
     * New last/family name. Same semantics as `given_name`.
     */
    family_name?: string | null;
    /**
     * New first/given name. Any non-empty value sets/replaces the
     * current value. Absent → no change.
     */
    given_name?: string | null;
    /**
     * Whether to receive an email when someone shares a resource with
     * the user. Absent → no change (existing setting preserved). Pass
     * `true` to opt in, `false` to opt out. Honored only on the
     * plain-notification path; magic-link first-invitations to externals
     * always send.
     */
    notify_on_share?: boolean | null;
    /**
     * New preferred locale (BCP-47 shape, e.g. `"fr"`, `"zh-TW"`).
     * Must resolve against the server's `LocaleRegistry` — unknown
     * codes are rejected with 400. Pass an empty string to clear the
     * preference back to the server default (the application layer
     * normalises `""` → `None`).
     */
    preferred_locale?: string | null;
    /**
     * Partial patch into the opaque UI preferences bag. **Must be a
     * JSON object.** Applied via a SHALLOW merge on the server:
     * keys present here overwrite existing top-level keys; keys not
     * present survive. A key value of `null` REMOVES that key from
     * the bag (implemented via `jsonb_strip_nulls` after the merge).
     *
     * Example: current bag `{"a":1,"b":2}`, patch `{"b":3,"c":4}`
     * → merged `{"a":1,"b":3,"c":4}`. Patch `{"a":null}` → `{"b":2}`.
     *
     * Absent → no change to the bag. This is a UI-only surface;
     * server never inspects the keys.
     */
    ui_preferences?: unknown;
    /**
     * Handle to claim (2-64 chars, `[A-Za-z0-9._-]+`, no `@`).
     * Accepted only when the caller currently has no username. Once
     * claimed the handle is permanent for the lifetime of the
     * account; subsequent attempts to set or change it via this
     * endpoint are rejected with 409. Admin override (via the
     * admin-create-user / admin-update-user surface, future PR) is
     * the escape hatch for genuine typos.
     */
    username?: string | null;
};

/**
 * `PUT /api/grants/role` — reconcile a subject's role on a resource.
 */
export type UpdateRoleDto = {
    /**
     * Optional expiry applied to every grant written or updated by this call.
     */
    expires_at?: string | null;
    resource: ResourceDto;
    role: RoleDto;
    subject: SubjectDto;
};

export type UpdateShareDto = {
    expires_at?: number | null;
    password?: string | null;
};

/**
 * Request body for updating a user's active status
 */
export type UpdateUserActiveDto = {
    active: boolean;
};

/**
 * Request body for updating a user's storage quota
 */
export type UpdateUserQuotaDto = {
    /**
     * Quota in bytes. Use 0 for unlimited.
     */
    quota_bytes: number;
};

/**
 * Request body for updating a user's role
 */
export type UpdateUserRoleDto = {
    role: string;
};

/**
 * Body for `POST /api/auth/upgrade-to-internal`. Converts an
 * authenticated external user into an internal user with their own
 * personal drive.
 *
 * `password` is optional — semantics decided per deployment:
 * * If `magic_link` is in `OXICLOUD_AUTH_METHODS` (and OIDC isn't
 * enabled) → password can be omitted; user remains magic-link-only
 * for login after upgrade.
 * * Otherwise → password is required; refusal returns 400
 * `error_type = "PasswordRequired"`. Without it the upgraded user
 * would have no login path.
 */
export type UpgradeToInternalDto = {
    password?: string | null;
};

/**
 * Response for querying upload session status.
 */
export type UploadStatusResponseDto = {
    bytes_received: number;
    completed_chunks: number;
    filename: string;
    is_complete: boolean;
    pending_chunks: Array<number>;
    progress: number;
    total_chunks: number;
    total_size: number;
    upload_id: string;
};

export type VerifyPasswordRequest = {
    password: string;
};

/**
 * One drive that would remain laxer than the candidate default.
 */
export type WeakerDriveDto = {
    id: string;
    /**
     * Which kind's default it is being judged against — the live report
     * lists both kinds together, and "Personal" is every personal drive's
     * name, so the row would otherwise be ambiguous.
     */
    kind: string;
    /**
     * The knobs on which it is laxer — the same per-knob verdict the scan
     * emits one finding per, so the two lists read identically.
     */
    knobs: Array<string>;
    name?: string | null;
};

/**
 * Read-only webhook info, shown beside SMTP on the admin Notifications
 * page. Like SMTP, configured only through environment variables.
 */
export type WebhookInfoDto = {
    /**
     * Whether `OXICLOUD_WEBHOOK_URL` is set and the sink was built.
     */
    enabled: boolean;
    /**
     * `generic`, `slack`, `discord`, `teams`, `telegram` or `ntfy`.
     */
    format: string;
    /**
     * Scheme and host of the endpoint — **never the full URL**.
     *
     * A Telegram endpoint embeds the bot token in its path
     * (`/bot<TOKEN>/sendMessage`), and a Slack or Discord webhook URL is
     * itself the credential: echoing either into an API response would
     * put a secret in a browser's network log and anywhere that response
     * gets pasted. The host is enough to confirm "it points where I
     * think".
     */
    host: string;
    /**
     * Recipient for the formats that carry one — a Telegram chat id, an
     * ntfy topic. Empty when unset or not applicable. Not a credential,
     * and an operator checking their configuration needs to see it.
     */
    target: string;
};

/**
 * Outcome of `POST /api/admin/webhook/test`.
 *
 * `code` + `message` mirror `SmtpTestResultDto` so the admin panel can
 * render both transports' diagnostics the same way.
 */
export type WebhookTestResultDto = {
    /**
     * HTTP status the receiver returned. Absent when nothing answered —
     * DNS failure, refused connection, timeout — which is itself the
     * diagnosis.
     */
    code?: number | null;
    /**
     * The receiver's own response body, truncated — or the transport
     * error when there was no response. Usually the useful part: a bare
     * 403 does not distinguish a revoked token from a disabled channel,
     * and the body says which.
     */
    message?: string | null;
    /**
     * Transport name, so a future second sink is distinguishable.
     */
    sink: string;
    success: boolean;
};

